+}
+
+.status-on {
+    background: #dcfce7;
+    color: #166534;
+}
+
+.status-off {
+    background: #fee2e2;
+    color: #991b1b;
+}
+
+.info-text {
+    font-size: 0.825rem;
+    color: #64748b;
+    margin-top: 0.75rem;
+}
+
+.error-text {
+    color: #dc2626;
+    font-size: 0.825rem;
+    margin-bottom: 0.75rem;
+}
+
+/* Sessions Table */
+.sessions-table-wrapper {
+    overflow-x: auto;
+}
+
+.sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    font-size: 0.875rem;
+}
+
+.sessions-table th,
+.sessions-table td {
+    padding: 0.625rem 0.75rem;
+    text-align: left;
+    border-bottom: 1px solid #e2e8f0;
+}
+
+.sessions-table th {
+    background: #f8fafc;
+    font-weight: 600;
+    color: #475569;
+}
+
+.sessions-table tr:hover {
+    background: #f8fafc;
+}
+
+.current-badge {
+    font-size: 0.75rem;
+    background: #dbeafe;
+    color: #1e40af;
+    padding: 0.125rem 0.5rem;
+    border-radius: 12px;
+}
+
+/* Modal */
+.modal-overlay {
+    position: fixed;
+    inset: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+.modal {
+    background: white;
+    padding: 1.5rem 2rem;
+    border-radius: 10px;
+    max-width: 420px;
+    width: 90%;
+    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
+}
+
+.modal h3 {
+    margin-top: 0;
+}
+
+/* Radio Group */
+.radio-group {
+    display: flex;
+    gap: 1.25rem;
+    margin-top: 0.25rem;
+}
+
+.radio-label {
+    display: flex;
+    align-items: center;
+    gap: 0.375rem;
+    cursor: pointer;
+}
+
+/* Appearance Preview */
+.appearance-preview {
+    border: 1px solid #e2e8f0;
+    border-radius: 8px;
+    overflow: hidden;
+    max-width: 500px;
+    margin-top: 0.75rem;
+    transition: all 0.2s ease;
+}
+
+.preview-header {
+    padding: 0.75rem 1rem;
